import{createHash}from'node:crypto';
import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const oldNames={recordingPreview:'liveRecordingPreviewAsync',recordingApply:'liveRecordingApplyAsync',undo:'liveUndoAsync',realtimePreview:'liveRealtimeArmPreviewAsync',realtimeApply:'liveRealtimeArmApplyAsync',disarm:'liveRealtimeDisarmAsync',stats:'liveRealtimeStatsAsync'};
function clean(v){v=JSON.parse(JSON.stringify(v));function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(willington_)/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v;}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function change(root,path,value,remove=false){let at=root;for(const key of path.slice(0,-1))at=at[key];if(remove)delete at[path.at(-1)];else at[path.at(-1)]=structuredClone(value);}
function setup(config={}){
 const sim=new DeterministicLiveSimulator();const other=structuredClone(sim.state.tracks[0]);Object.assign(other,{ref:'track:other',name:'Other',objectIdentity:'simulator:track:other',devices:[]});for(const key of ['volumeRef','panRef','cueRef','volumeIdentity','panIdentity','cueIdentity'])other.mixer[key]=null;other.mixer.sendRefs=[];other.mixer.sendIdentities=[];other.mixer.sends=[];sim.state.tracks.push(other);sim.state.tracks.forEach(t=>t.armed=true);sim.state.willington={names:{'macro-name':'Macro 1','variation-name':'Variation 1'},mapping:null,zone:{minimum:12,maximum:104,fadeMinimum:24,fadeMaximum:88}};for(const p of config.patches??[])change(sim.state,p.path,p.value,p.remove);
 const calls=[],cache=new Map(),overrides={provenance:'real-live',registryHash:'a'.repeat(64),...config.status};let fault='',fired=false,armed=false,pending,controller;
 const status=()=>({...sim.status(),...overrides,operations:overrides.operations??[...sim.status().operations,'realtime.arm','realtime.disarm','realtime.stats','willington.device.read','willington.device.set']});
 function once(){if(fired)return false;fired=true;return true;}
 async function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(c?.transactionId&&cache.has(key))return cache.get(key);
 if(['before','cancel','refusal'].includes(fault)&&once())throw fault==='refusal'?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault==='cancel'?'operation cancelled before dispatch':'injected operation failure');
 if(fault==='during-invoke')controller?.abort();if(fault==='no-effect'&&once())return {changed:true};
 let result;if(i.operation==='realtime.arm'){armed=true;await new Promise(r=>setTimeout(r,1));result={host:'127.0.0.1',port:9766,token:'t'.repeat(32),expiresAt:Date.now()+i.args.ttlMs,channels:i.args.channels,parameterRefs:i.args.parameterRefs,packetLimitBytes:512,ratePerSecond:64,burst:16};if(config.endpoint)Object.assign(result,config.endpoint);}else if(i.operation==='realtime.disarm'){armed=false;result={armed:false};}else if(i.operation==='realtime.stats')result={armed,accepted:2,pending:0};else if(i.operation.startsWith('willington.device.')){const args=i.args,kind=args.kind,mock=sim.state.willington;function read(){const state=String(kind).endsWith('-zone')?{...mock.zone,lowerBound:kind==='velocity-zone'?1:0,upperBound:127,deviceIdentity:'rack',targetIdentity:'chain',rackClass:'InstrumentGroupDevice'}:kind==='macro-mapping'?{mapping:JSON.stringify(mock.mapping),parameterValue:0.5,parameterMin:0,parameterMax:1,macroValues:'[0]',targetIdentity:'target',deviceIdentity:'rack'}:{name:mock.names[kind],deviceIdentity:'rack'};return {state,stateRevision:createHash('sha256').update(JSON.stringify(state)).digest('hex')}}
 if(i.operation==='willington.device.read')result=read();else{if(args.expectedStateRevision!==read().stateRevision)throw Error('Willington target changed since preview or after apply; undo refused');if(String(kind).endsWith('-zone'))mock.zone=structuredClone(args.next);else if(kind==='macro-mapping')mock.mapping=args.next.mapping;else mock.names[kind]=args.next.name;result={changed:true,revision:1,...read()};}if('readOverride'in config&&i.operation==='willington.device.read')result=structuredClone(config.readOverride);
 }else {if(fault==='delayed'&&!fired)pending=structuredClone(sim.state.playback);result=sim.invoke(i);}
 if(fault==='null'&&once())result=null;if(fault==='false'&&once())result={recording:'yes',armed:'no'};if(fault==='no-effect'&&once()){sim.state.playback.transport.sessionRecord=false;sim.state.playback.transport.arrangementRecord=false;}
 if(c?.transactionId)cache.set(key,result);if(fault==='after'&&once())throw Error('injected operation failure');return result;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));if(fault==='read'&&once())throw Error('injected authoritative read failure');if(pending){const v=sim.snapshot();v.playback=pending;pending=undefined;fired=true;return v;}return sim.snapshotAsync(c,r);},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));if(r.kind==='session-playback'&&fault==='playback-read'&&once())throw Error('injected authoritative read failure');const result=await sim.discoverAsync(r,c);if(r.kind==='session-playback'&&pending){result.items=[pending];pending=undefined;fired=true;}return result},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));return sim.get(r)},invokeAsync:invoke,refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));if(fault==='status'&&once())throw Error('injected status failure');if(fault==='during-status')controller?.abort();return status();}};
 return {host:new McpHost(adapter),sim,calls,overrides,get armed(){return armed},set fault(v){fault=v;fired=false},set controller(v){controller=v}};
}

const names={willingtonPreview:"liveWillingtonPreviewAsync",willingtonApply:"liveWillingtonApplyAsync",undo:"liveUndoAsync"};


const rows=[],workflows=[];
async function workflow(label,config,steps){const a=setup(config),results=[],states=[];let tx;async function call(step,id){const args=structuredClone(step.args??{});if(args.transactionId==='$transaction')args.transactionId=tx;const controller=new AbortController();a.controller=controller;if(step.abort)controller.abort();let result;try{result=await a.host[names[step.tool]](id,args,controller.signal)}catch(e){result={thrown:e.message}};if(step.tool.endsWith('Preview')){try{tx=JSON.parse(result.result.content[0].text).transactionId}catch{}}return clean(result);}
 for(const step of steps){if(step.patch){change(a.sim.state,step.patch.path,step.patch.value,step.patch.remove);continue;}if(step.status){Object.assign(a.overrides,step.status);continue;}if(step.record){if(tx)Object.assign(a.host.clipLifecycleTransactions.get(tx),step.record);continue;}if('fault'in step){a.fault=step.fault;continue;}
 if(step.concurrent){const offset=results.length;results.push(...await Promise.all(step.concurrent.map((s,i)=>call(s,offset+i+1))));}else results.push(await call(step,results.length+1));states.push(tx?clean(a.host.clipLifecycleTransactions.get(tx)):null);}
 workflows.push({label,config,steps,results,states,calls:a.calls,target:clean(a.sim.state.willington)});}
const apply=(family,key='apply-key',extra={})=>({tool:family+'Apply',args:{transactionId:'$transaction',confirmation:'apply',idempotencyKey:key},...extra});
const modes={macro:{ref:'rack',kind:'macro-name',macroIndex:0,name:'New macro'},variation:{ref:'rack',kind:'variation-name',name:'New variation'},continuous:{ref:'rack',kind:'macro-mapping',targetRef:'target',mappingIndex:0,minimum:0.75,maximum:0.25,mappingKind:'continuous'},enum:{ref:'rack',kind:'macro-mapping',targetRef:'target',mappingIndex:15,minimum:0,maximum:1,mappingKind:'enum'},boolean:{ref:'rack',kind:'macro-mapping',targetRef:'target',mappingIndex:3,minimum:40,maximum:100,mappingKind:'boolean'},unmap:{ref:'rack',kind:'macro-mapping',targetRef:'target',mappingIndex:null},...Object.fromEntries(['selector-zone','key-zone','velocity-zone'].map(kind=>[kind,{ref:'rack',kind,targetRef:'chain',minimum:16,maximum:40,fadeMinimum:20,fadeMaximum:36}]))};
for(const[mode,valid]of Object.entries(modes)){const keys=['ref','kind','macroIndex','targetRef','name','mappingIndex','minimum','maximum','mappingKind','fadeMinimum','fadeMaximum'];const cases=[null,[],{},false,0,'x',valid,{...valid,extra:true}];for(const key of keys){const missing={...valid};delete missing[key];cases.push(missing);for(const value of [null,[],{}, {toString:1},true,false,-1,0,0.5,1,15,16,127,128,'','x','continuous','enum','boolean',['key-zone'],'x'.repeat(257),'a\0b'])cases.push({...valid,[key]:value});}for(const args of cases){const a=setup();let result;try{result=clean(await a.host.liveWillingtonPreviewAsync(1,args))}catch(e){result={thrown:e.message}}rows.push({mode,tool:'willingtonPreview',args,result});}}
for(const args of [null,[],{}, {transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'}])rows.push({tool:'willingtonApply',args,result:clean(await setup().host.liveWillingtonApplyAsync(1,args))});
for(const[mode,args]of Object.entries(modes))for(const scenario of ['normal','expire','epoch','disconnected','operation','kind-unavailable','transport','apply-edit','apply-before','apply-after','apply-cancel','apply-refusal','apply-null','apply-false','apply-no-effect','apply-status','undo-before','undo-after','undo-refusal','undo-null','undo-no-effect','undo-edit','undo-status']){
 const patches=[],config={patches};if(mode==='unmap')patches.push({path:['willington','mapping'],value:{index:0,minimum:0,maximum:1,kind:'continuous'}});if(scenario==='disconnected')config.status={connected:false};if(scenario==='operation')config.status={operations:[]};if(scenario==='kind-unavailable')config.status={willingtonKinds:[]};if(scenario==='transport')patches.push({path:['playback','transport','playing'],value:true});
 const steps=[{tool:'willingtonPreview',args}];if(scenario==='expire')steps.push({record:{expiresAt:0}});if(scenario==='epoch')steps.push({status:{epoch:99}});const changed=mode.endsWith('-zone')?{path:['willington','zone','fadeMaximum'],value:80}:args.kind==='macro-mapping'?{path:['willington','mapping'],value:{index:2}}:{path:['willington','names',args.kind],value:'External'};
 if(scenario==='apply-edit')steps.push({patch:changed});if(scenario.startsWith('apply-')&&scenario!=='apply-edit')steps.push({fault:scenario.slice(6)});steps.push(apply('willington'),apply('willington','other-key'),apply('willington'),{fault:''});if(scenario==='undo-edit')steps.push({patch:changed});if(scenario.startsWith('undo-')&&scenario!=='undo-edit')steps.push({fault:scenario.slice(5)});for(const key of ['undo-key','other-undo-key','undo-key'])steps.push({tool:'undo',args:{transactionId:'$transaction',confirmation:'undo',idempotencyKey:key}});await workflow(mode+'/'+scenario,config,steps);
}
for(const[mode,args]of Object.entries(modes))for(const readOverride of [null,false,{}, {state:null},{state:{}},{state:{mapping:'bad',name:'Name',parameterValue:1,parameterMin:0,parameterMax:127},stateRevision:'opaque'}])await workflow('read/'+mode+'/'+JSON.stringify(readOverride),{readOverride},[{tool:'willingtonPreview',args}]);
fs.writeFileSync(new URL('host-willington-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
